             for pname, param in sig.parameters.items()
             if pname not in {"self", "cls"}
             and pname != self._context_parameter_name
             and param.kind not in {inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD}
         }
