+    return apiError("invalid_request", 400);
+  }
+  if (!isChatRequest(body)) {
+    return apiError("invalid_request", 400);
+  }
+
+  const payload = {
+    message: body.message.trim(),
+    ...(body.product_id ? { product_ids: [body.product_id.trim()] } : {}),
